function inferMedicalRoleFromText(text, depth) {
  if (depth === 0) return "root";
  const lower = text.toLowerCase();
  if (/\b(red flag|warning|danger|emergency|complication|toxic|contraindic|shock|arrest|lethal|critical)\b/.test(
    lower
  ) || /(تحذير|خطر|مضاعف|طوارئ|تسمم|موانع|صدمة|حرج)/.test(lower)) {
    return "warning";
  }
  if (/\b(treat|therap|drug|medicat|manage|antibiotic|dose|surgery|intervent|first-line|inhibitor|blocker|statin|insulin)\b/.test(
    lower
  ) || /(علاج|دواء|أدوية|تدبير|جراحة|مثبط|حاصر|جرعة|تدخل)/.test(lower)) {
    return "treatment";
  }
  if (/\b(diagnos|test|lab|ecg|ekg|xray|ct|mri|ultrasound|biopsy|criteria|score|symptom|sign|present|workup|exam)\b/.test(
    lower
  ) || /(تشخيص|فحص|تحليل|تخطيط|أشعة|أعراض|علامات|معايير|خزعة)/.test(lower)) {
    return "diagnosis";
  }
  if (/\b(pathophys|mechan|etiolog|cause|pathway|cascade|receptor|enzyme|gene|ischemi|inflam|mediat)\b/.test(
    lower
  ) || /(آلية|فيزيولوج|مسبب|أسباب|مسار|مستقبل|إنزيم|التهاب|نقص تروية)/.test(lower)) {
    return "mechanism";
  }
  return "concept";
}
